const profiles=[{"name":"Ledger","role":"Your calm fact-checker","question":"“Let’s start with<br>what we know.”","scope":"I’m the steady one with the receipts. I check the payment, amount, and order reference, then explain what those records actually tell us.","to":"Relay","quote":"Good news: I found one completed $128 payment for this order. Relay, can you follow what happened when we told the store?","evidence":"Completed PayPal capture · Order #1048","boundary":"I’ll separate the facts from the assumptions. A paid transaction alone doesn’t tell us whether the order shipped."},{"name":"Relay","role":"Your curious investigator","question":"“I’ll follow<br>the trail with you.”","scope":"I’m happiest connecting the dots. I follow the message from PayPal to the store and flag the exact handoff that needs a closer look.","to":"Patch","quote":"Found the handoff! The store acknowledged the message at 10:42:04. Patch, your turn—did the order update after that?","evidence":"Event delivery acknowledgment · HTTP 200","boundary":"I won’t confuse “message received” with “job finished.” We still need to see what the store did next."},{"name":"Patch","role":"Your practical fixer","question":"“Let’s find the<br>smallest useful fix.”","scope":"I’m here to make the next step manageable. I compare the store records, explain the mismatch, and help shape a correction you can review.","to":"Prism","quote":"Here’s the snag: the database update timed out a second later, so the order stayed unpaid. We found the failed step; we don’t yet know why it timed out.","evidence":"Store processing log · Database timeout","boundary":"I’ll show you exactly what would change. The correction waits for your approval."},{"name":"Prism","role":"Your thoughtful reviewer","question":"“Let’s make sure<br>this really helps.”","scope":"I’m the second pair of eyes. I ask the awkward questions now, so you can make a clearer decision later. You stay in charge of every correction.","to":"Relay","quote":"Nice catch, Relay. We know the message arrived—but did the order actually update? Let’s check before we call this solved.","evidence":"Event delivery + store processing log","boundary":"I won’t call a case fixed just because we all agree. Fresh records have to agree, too."}];
function selectAgent(i){const a=profiles[i];document.querySelectorAll('[data-agent]').forEach(b=>b.setAttribute('aria-pressed',String(Number(b.dataset.agent)===i)));document.getElementById('agent-label').textContent=a.name.toUpperCase()+' / '+a.role.toUpperCase();document.getElementById('agent-question').innerHTML=a.question;document.getElementById('agent-scope').textContent=a.scope;document.getElementById('consultation-avatar').className='portrait portrait-'+i+' agent-avatar';for(const [id,value] of Object.entries({'consultation-from':a.name,'consultation-to':a.to,'consultation-quote':a.quote,'consultation-evidence':a.evidence,'agent-boundary':a.boundary}))document.getElementById(id).textContent=value;}
document.querySelectorAll('[data-agent]').forEach(b=>b.addEventListener('click',()=>selectAgent(Number(b.dataset.agent))));document.querySelectorAll('[data-meet]').forEach(b=>b.addEventListener('click',()=>selectAgent(Number(b.dataset.meet))));selectAgent(3);
